import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BS0bAV7E.js";const b=JSON.parse('{"title":"Boot flow, instruction by instruction","description":"","frontmatter":{},"headers":[],"relativePath":"arch/boot-flow.md","filePath":"arch/boot-flow.md"}'),r={name:"arch/boot-flow.md"};function s(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="boot-flow-instruction-by-instruction" tabindex="-1">Boot flow, instruction by instruction <a class="header-anchor" href="#boot-flow-instruction-by-instruction" aria-label="Permalink to &quot;Boot flow, instruction by instruction&quot;">​</a></h1><h2 id="stage-0-firmware-grub" tabindex="-1">Stage 0 - firmware + GRUB <a class="header-anchor" href="#stage-0-firmware-grub" aria-label="Permalink to &quot;Stage 0 - firmware + GRUB&quot;">​</a></h2><p>The ISO carries two boot images (legacy El Torito + EFI). Either way GRUB 2.12 runs, shows the slot menu (ISO / A / B - the flag lives on the target disk), and loads <code>boot/opencube.elf</code> with the multiboot2 protocol. GRUB also attaches the kernel ELF itself as a module with cmdline <code>self</code> - the installer payload pattern.</p><h2 id="stage-1-boot-s-32-64-bit" tabindex="-1">Stage 1 - boot.S (32 -&gt; 64 bit) <a class="header-anchor" href="#stage-1-boot-s-32-64-bit" aria-label="Permalink to &quot;Stage 1 - boot.S (32 -&gt; 64 bit)&quot;">​</a></h2><p><code>boot/boot.S</code> is the 32-bit entry: GRUB calls it in protected mode, paging off, <code>eax=0x36d76289</code>, <code>ebx=mbi pointer</code>. It:</p><ol><li>Sets up its own GDT.</li><li>Builds page tables identity-mapping the first 4 GiB with 2 MiB pages.</li><li>Enables PAE, LME, PGE.</li><li>Jumps to 64-bit long mode and calls <code>kmain</code>.</li></ol><h2 id="stage-2-multiboot2-parse" tabindex="-1">Stage 2 - multiboot2 parse <a class="header-anchor" href="#stage-2-multiboot2-parse" aria-label="Permalink to &quot;Stage 2 - multiboot2 parse&quot;">​</a></h2><p><code>kernel/arch/x86_64/arch_multiboot2.c</code> walks the tag list. Tags are packed types (all of them - the generic tag header, framebuffer, mmap, meminfo, strings, modules, RSDP carriers). The parser is hostile-input hardened (BUG-0142 fix): total_size bounds, per-tag minimums, string NUL-termination, truncated-tag rejection - a malformed mbi degrades gracefully instead of reading past the structure.</p><p>It extracts: framebuffer geometry, the physical memory map, the command line, module list, and the ACPI RSDP (tags 14/15 - the ACPI driver re-validates the signature at that address).</p><h2 id="stage-3-kmain-bring-up" tabindex="-1">Stage 3 - kmain bring-up <a class="header-anchor" href="#stage-3-kmain-bring-up" aria-label="Permalink to &quot;Stage 3 - kmain bring-up&quot;">​</a></h2><p><code>kernel/main.c</code> in boot-log order: framebuffer console + 8x16 font, IDT/GDT/TSS (256 gates, IST1 panic stack, IST2 debug stack), 8259 remap, PIT 100 Hz, PS/2 keyboard, COM1 RX into the keyboard queue, line editor, <code>sti</code>, and a live exception self-test (3/3: #DE #UD #PF caught, kernel alive) before anything else trusts the trap path.</p><p>Then: PMM (bitmap from the mmap), VMM, heap; driver domains; VFS with the ramfs root; network; shell registration (233 commands); crash recovery armed; <code>oc&gt;</code> prompt.</p><h2 id="the-two-stage-link" tabindex="-1">The two-stage link <a class="header-anchor" href="#the-two-stage-link" aria-label="Permalink to &quot;The two-stage link&quot;">​</a></h2><p>The kernel links in two passes (<code>Makefile</code>): stage-1 links everything except the GRUB boot images; <code>tools/embed_grub.py</code> then generates <code>kernel/generated/grub_boot_data.c</code> embedding the 512-byte boot.img plus a core.img built by <code>grub-mkimage</code> (the module set the on-disk grub.cfg needs - biosdisk, part_msdos, fat, multiboot2, search, serial console...); stage-2 links that in. This is how the in-system <code>install</code>/<code>abdisk</code>/<code>grub-install</code> commands can write a bootable disk without external files: the boot loader is inside the kernel.</p>',14)])])}const g=t(r,[["render",s]]);export{b as __pageData,g as default};
